/* 
** This function allocates a new parser.
** The only argument is a pointer to a function which works like
** malloc.
**
** Inputs:
** A pointer to the function used to allocate memory.
**
** Outputs:
** A pointer to a parser.  This pointer is used in subsequent calls
** to MyLiteLemon and MyLiteLemonFree.
*/
void *MyLiteLemonAlloc(void *(*mallocProc)(YYMALLOCARGTYPE) MyLiteLemonCTX_PDECL){
  yyParser *yypParser;
  yypParser = (yyParser*)(*mallocProc)( (YYMALLOCARGTYPE)sizeof(yyParser) );
  if( yypParser ){
    MyLiteLemonCTX_STORE
    MyLiteLemonInit(yypParser MyLiteLemonCTX_PARAM);
  }
  return (void*)yypParser;
}
#endif /* MyLiteLemon_ENGINEALWAYSONSTACK */


